window.ECBA_QUESTION_BANK=window.ECBA_QUESTION_BANK||[];window.ECBA_QUESTION_BANK.push(...[{"id":"q333","domains":[7],"level":3,"tag":"Inclusion and representation","q":"A team’s workshops repeatedly hear from the same few groups, while other impacted stakeholders are absent. What response best reflects the Standard’s guidance on inclusion and representation?","opts":["Continue with the most senior voices to keep decisions quick","Actively seek and amplify diverse stakeholder perspectives","Ask absent stakeholders to review the final solution only","Avoid including different perspectives until implementation"],"answer":[1],"why":["Relying only on senior voices can leave important experiences and needs unrepresented.","Correct. The Standard emphasizes actively cultivating diverse perspectives and ensuring stakeholders can contribute.","A late review may miss opportunities for those stakeholders to shape the understanding and options early.","Inclusion should inform planning and decision-making across the initiative, not be postponed until implementation."],"ref":"Chapter 4, §4.5.3, p. 19","multi":false,"sourceSet":"ecba-20-untimed-practice.html"},{"id":"q334","domains":[],"level":1,"tag":"Applying business analysis tasks","q":"A project manager expects every business analysis task to be completed once, in a fixed sequence. What should the business analyst explain?","opts":["Tasks may be iterative, concurrent, and performed in an order that fits the initiative","Tasks must always follow the BABOK Guide list order","Only the first task may be repeated","Tasks are relevant only before solution implementation"],"answer":[0],"why":["Correct. The Standard says tasks need not be linear; they may occur concurrently, repeat, and be applied flexibly to context.","The Standard explicitly notes that tasks can be referenced and implemented in the order that best suits the work.","The Standard allows tasks to be managed, reviewed, and repeated as needed, not only the first task.","The task set supports work from understanding needs through solution implementation and beyond."],"ref":"Chapter 5, §5.1, p. 21","multi":false,"sourceSet":"ecba-20-untimed-practice.html"},{"id":"q335","domains":[7],"level":2,"tag":"Task card structure","q":"A business analyst is preparing a task card for stakeholders. Which set of information matches the structure described in the Standard?","opts":["Purpose or need, value, output or outcome, stakeholders, and description of change","Budget, schedule, vendor, acceptance date, and contract status","Problem statement, test scripts, training deck, and release notes only","Task owner, due date, status, and escalation path only"],"answer":[0],"why":["Correct. Task cards include purpose or need, value, solution output or outcome, stakeholders, and description of change.","These may be project management details but are not the task card structure specified in the Standard.","Some artifacts may relate to specific tasks, but this list omits several core task card elements.","Administrative tracking fields alone do not provide the task card’s purpose, value, solution, and stakeholder context."],"ref":"Chapter 5, §5.2, p. 21","multi":false,"sourceSet":"ecba-20-untimed-practice.html"},{"id":"q336","domains":[5],"level":1,"tag":"Verify and validate","q":"A reviewer checks whether a requirement is clear, internally consistent, and detailed enough for its intended use. Which task is the reviewer performing?","opts":["Validate Requirements and Designs","Verify Requirements and Designs","Assess Risks","Confirm Elicitation Results"],"answer":[1],"why":["Validation checks alignment with business requirements, goals, and value; this scenario focuses on specification quality.","Correct. Verification checks that requirements and designs are of sufficient quality, internally consistent, and usable for their purpose.","Risk assessment considers uncertainties and their consequences, not the quality of requirement wording.","Confirming elicitation results checks the accuracy of elicited information, not the quality of a specified requirement."],"ref":"Chapter 5, Verify Requirements and Designs, p. 43; Validate Requirements and Designs, p. 44","multi":false,"sourceSet":"ecba-20-untimed-practice.html"},{"id":"q337","domains":[8],"level":2,"tag":"Risk","q":"Before a transition begins, the analyst identifies uncertainty about supplier readiness and estimates how it could affect delivery of value. Which task best fits?","opts":["Define Future State","Assess Risks","Approve Requirements and Designs","Measure Solution Performance"],"answer":[1],"why":["Defining future state describes desired conditions and objectives, rather than analyzing uncertainty.","Correct. Assess Risks examines uncertain internal and external forces, their potential consequences, and possible responses.","Approval authorizes requirements and designs; it does not evaluate supplier uncertainty and its effects.","Measuring solution performance assesses how a solution performs against measures, not pre-transition uncertainty."],"ref":"Chapter 5, Assess Risks, p. 40","multi":false,"sourceSet":"ecba-20-untimed-practice.html"},{"id":"q338","domains":[4],"level":3,"tag":"Strategy analysis","q":"An organization agrees on its desired outcomes and conditions, then compares a gradual transition with a single large transformation. Which pairing of tasks is most appropriate?","opts":["Define Future State to establish the desired conditions; Define Change Strategy to compare transition approaches","Analyze Current State to set desired conditions; Assess Risks to select the transition approach","Define Change Strategy to establish desired outcomes; Define Future State to compare delivery options","Specify Requirements and Designs to select the transition approach; Validate Requirements to define outcomes"],"answer":[0],"why":["Correct. Define Future State establishes the conditions and objectives needed to meet the need; Define Change Strategy assesses alternative approaches, including evolutionary or transformational change.","Analyzing Current State describes the existing situation, while Assess Risks addresses uncertainty; neither replaces these two tasks.","This reverses the purposes of the tasks: future state defines desired conditions, and change strategy selects the approach.","Specification and validation concern requirements and designs, not defining the desired enterprise state and transition strategy."],"ref":"Chapter 5, Define Future State, p. 39; Define Change Strategy, p. 41","multi":false,"sourceSet":"ecba-20-untimed-practice.html"},{"id":"q339","domains":[6,8],"level":3,"tag":"Potential value and solution recommendation","q":"Three solution options have different benefits, costs, risks, and constraints. What should the business analyst do before recommending one?","opts":["Choose the option with the most features","Compare the options’ potential value and trade-offs for stakeholders","Recommend the option already preferred by the sponsor","Select the option that can be delivered first, regardless of outcomes"],"answer":[1],"why":["Feature count alone does not establish which option delivers the greatest overall value.","Correct. The task evaluates design options, including benefits, associated costs, constraints, and trade-offs, to recommend the most appropriate solution.","Sponsor input is relevant, but the recommendation should be based on an objective evaluation of the options and stakeholder value.","Speed may matter, but it must be considered alongside expected value, cost, risk, and constraints."],"ref":"Chapter 5, Analyze Potential Value and Recommend Solution, p. 47","multi":false,"sourceSet":"ecba-20-untimed-practice.html"},{"id":"q340","domains":[],"level":2,"tag":"The Standard summary","q":"A new colleague asks what the Business Analysis Standard contributes to their practice. Which response best reflects the summary chapter?","opts":["It provides a concise introduction, foundational terms, mindset and competencies, and examples of 30 tasks across six knowledge areas","It prescribes a single lifecycle and detailed solution design for every initiative","It replaces the BABOK Guide and all other IIBA resources","It is limited to requirements documentation for software projects"],"answer":[0],"why":["Correct. The summary highlights the Standard’s introduction to foundational concepts, mindset, competencies, techniques, and 30 tasks across six knowledge areas and varied contexts.","The Standard does not require one lifecycle or prescribe every solution design; approaches depend on context.","It is a simplified foundation and gateway to more detailed IIBA resources, not a replacement for them.","The Standard applies broadly across business contexts and types of initiatives, not only software documentation."],"ref":"Chapter 6, Summary, p. 53","multi":false,"sourceSet":"ecba-20-untimed-practice.html"},{"id":"q341","domains":[1],"level":1,"tag":"BACCM relationships","q":"A new returns service improves customer speed but increases handling cost and conflicts with an existing eligibility policy. What is the best next analysis?","opts":["Assess how need, change, solution, stakeholders, context, and value relate","Treat reduced handling cost as value and retain the current policy","Define customer speed as the need and select the solution","Treat policy as context and assess value only after implementation"],"answer":[0],"why":["Correct: BACCM concepts are interrelated; analyze them together in context.","This considers one value measure while overlooking other stakeholders and the policy impact.","This narrows the need and commits to a solution before examining context.","Policy is a constraint to analyze now, and value can be assessed before implementation."],"ref":"BABOK v3 §2.1 pp. 12–13; Blueprint p. 2, D1","multi":false,"sourceSet":"ecba-30-timed-practice-set-6.html"},{"id":"q342","domains":[1],"level":1,"tag":"Requirement classification","q":"A claims portal must allow photo uploads, respond within two seconds, and temporarily convert legacy records. How are these best classified?","opts":["Functional; transition; non-functional","Solution functional; solution non-functional; transition","Business; stakeholder; solution functional","Stakeholder; solution non-functional; business"],"answer":[1],"why":["The response-time threshold is a quality attribute, while conversion is temporary transition capability.","Correct: upload is solution functionality, response time is non-functional, and conversion supports transition.","The first is not the business objective; the latter classifications do not fit the examples.","Photo upload is solution functionality; conversion is not the business requirement itself."],"ref":"BABOK v3 §2.3 p. 16; Blueprint p. 2, D1","multi":false,"sourceSet":"ecba-30-timed-practice-set-6.html"},{"id":"q343","domains":[1],"level":2,"tag":"Requirements and designs","q":"A prototype reveals users need to compare current and previous claim decisions. What should the BA conclude?","opts":["Design replaces the original requirement once approved","Record the need only as a design detail","Defer it until implementation so the baseline stays stable","Design exploration can reveal a new requirement to analyze and manage"],"answer":[3],"why":["A design does not eliminate analysis of new needs.","Discovery through design does not turn a stakeholder need into design only.","Deferral risks losing an important need and is not required to preserve a baseline.","Correct: requirements and designs are distinct but related, and design can reveal additional requirements."],"ref":"BABOK v3 §2.4 p. 19; Blueprint p. 2, D1","multi":false,"sourceSet":"ecba-30-timed-practice-set-6.html"},{"id":"q344","domains":[1],"level":3,"tag":"Business analysis and value","q":"A project meets schedule and budget, but customer outcomes are unchanged. What is the best conclusion?","opts":["Value was delivered because project measures met target","Solution success is established by delivery tolerances","Assess value against stakeholder outcomes; delivery performance alone is insufficient","Reclassify the unmet outcome as a solution requirement"],"answer":[2],"why":["Schedule and budget measure project performance, not stakeholder value.","Tolerance compliance does not establish that needs were met.","Correct: value is assessed in context against stakeholder outcomes and needs.","A lack of outcome does not change the requirement classification."],"ref":"BABOK v3 §§2.1–2.2 pp. 12–14; Blueprint p. 2, D1","multi":false,"sourceSet":"ecba-30-timed-practice-set-6.html"},{"id":"q345","domains":[2],"level":1,"tag":"Ethical analysis","q":"An eligibility rule meets its overall target but disproportionately rejects applicants with a disability. The sponsor asks to report only the aggregate. What should the BA do?","opts":["Report the aggregate and defer subgroup review","Share the evidence, assess impacts and risks, and raise it appropriately","Recommend the rule because its approved target is met","Wait for sponsor direction before recording the disparity"],"answer":[1],"why":["Deferring material evidence can conceal stakeholder harm.","Correct: ethical practice requires transparency and attention to stakeholder impacts.","An aggregate target does not resolve unequal outcomes.","The concern should be documented and analyzed, not suppressed pending preference."],"ref":"BABOK v3 Chapter 9 pp. 188–216; Blueprint p. 5, D2","multi":false,"sourceSet":"ecba-30-timed-practice-set-6.html"},{"id":"q346","domains":[2],"level":2,"tag":"Adaptability","q":"Newly available stakeholder feedback challenges an assumption in approved analysis. What response best reflects adaptability and rigor?","opts":["Revisit the assumption, assess impacts, and adjust the analysis as needed","Keep the analysis unchanged and record feedback for a later release","Replace the approach immediately without impact assessment","Ask the sponsor whether the feedback should be examined"],"answer":[0],"why":["Correct: adapt to new evidence while assessing consequences and maintaining rigor.","This preserves the baseline but may ignore material new information.","Changing course without assessing impacts can disrupt dependent work.","The BA can examine relevance before seeking a decision on resulting change."],"ref":"BABOK v3 Chapter 9 pp. 188–216; Blueprint p. 5, D2","multi":false,"sourceSet":"ecba-30-timed-practice-set-6.html"},{"id":"q347","domains":[2],"level":2,"tag":"Systems thinking","q":"A change saves billing time but increases support corrections and delays revenue recognition. Which mindset is most useful?","opts":["Focus on billing because it owns the process","Measure billing first and inspect downstream effects only after a miss","Treat support effort as a separate operational issue","Examine effects across connected processes and stakeholder groups"],"answer":[3],"why":["A single-team view misses cross-system effects.","Known downstream impacts should be considered before waiting for a target miss.","The changed process may cause those effects, so they are relevant to analysis.","Correct: systems thinking examines relationships and consequences across the broader system."],"ref":"BABOK v3 Chapter 9 pp. 188–216; Blueprint p. 5, D2","multi":false,"sourceSet":"ecba-30-timed-practice-set-6.html"},{"id":"q348","domains":[2],"level":3,"tag":"Listening and communication","q":"An interviewee calls approval 'simple' but pauses when describing delays. What should the BA do?","opts":["Record the word simple and proceed","Ask a neutral follow-up and invite an example of the delay","Explain the expected process for confirmation","Infer opposition and document it as a concern"],"answer":[1],"why":["This misses a potentially meaningful cue.","Correct: active listening uses neutral clarification of verbal and non-verbal cues.","Supplying an interpretation can bias the response.","A pause is a prompt to explore, not proof of opposition."],"ref":"BABOK v3 Chapter 9 pp. 188–216; Blueprint p. 5, D2","multi":false,"sourceSet":"ecba-30-timed-practice-set-6.html"},{"id":"q349","domains":[3],"level":2,"tag":"Tailoring the BA approach","q":"A program has a stable regulatory conversion and an uncertain customer feature. Which BA approach fits best?","opts":["Adaptive for both because one stream is uncertain","Predictive for both because one stream is regulated","Tailor by workstream with coordinated predictive and adaptive practices","Use the most documented method consistently"],"answer":[2],"why":["Uncertainty in one stream does not dictate the other stream's method.","Regulation does not automatically require one approach for every workstream.","Correct: tailor the approach to context and coordinate dependencies.","Documentation volume alone is not the selection criterion."],"ref":"BABOK v3 §3.1 pp. 24–30; Blueprint p. 2, D3","multi":false,"sourceSet":"ecba-30-timed-practice-set-6.html"},{"id":"q350","domains":[3],"level":3,"tag":"Roles and governance","q":"A product owner controls backlog order; a compliance lead approves policy interpretation. One item affects both. What should the BA do?","opts":["Route the whole item to the product owner","Route the whole item to compliance","Escalate directly and bypass both roles","Route each decision to its authorized role and clarify interaction"],"answer":[3],"why":["Backlog authority may not include policy interpretation.","Compliance authority may not include product prioritization.","Defined decision rights should be used unless a conflict requires escalation.","Correct: apply governance to each decision and manage the approval dependency."],"ref":"BABOK v3 §3.3 pp. 37–41; Blueprint p. 2, D3","multi":false,"sourceSet":"ecba-30-timed-practice-set-6.html"},{"id":"q351","domains":[4],"level":1,"tag":"Current-state analysis","q":"A team estimates approvals take five days; logs show a two-day median and twelve-day complex cases. What next?","opts":["Validate the evidence and segment variation and stakeholder experience","Set a two-day future target from the median","Accept the team's estimate as operational truth","Replace the process because variation proves failure"],"answer":[0],"why":["Correct: validate evidence and understand variation before conclusions or change.","A median is not automatically a desired future target.","Experience is useful but should be reconciled with other evidence.","Variation calls for causal analysis before choosing a solution."],"ref":"BABOK v3 §6.1 pp. 103–109; Blueprint p. 2, D4","multi":false,"sourceSet":"ecba-30-timed-practice-set-6.html"},{"id":"q352","domains":[4],"level":2,"tag":"Future-state definition","q":"Stakeholders agree on fewer repeat contacts but disagree on self-service versus staffed support. What should be defined first?","opts":["A detailed self-service design","A future-state description of outcomes and capabilities, before channel selection","A current-state map with disagreement logged as risk","A prioritized backlog assuming self-service"],"answer":[1],"why":["This selects a channel before options are compared.","Correct: define desired outcomes and capabilities without prematurely fixing the solution.","Current-state analysis can help but does not establish shared future direction.","It represents an unsettled channel choice as an agreed solution."],"ref":"BABOK v3 §6.2 pp. 110–119; Blueprint p. 2, D4","multi":false,"sourceSet":"ecba-30-timed-practice-set-6.html"},{"id":"q353","domains":[4],"level":3,"tag":"Change impact","q":"A policy change fixes an exception but affects a vendor contract and downstream reporting. What is the strongest response?","opts":["Assess only the policy because other teams own their processes","Approve it and delegate downstream impacts to implementation","Trace impacts across processes, stakeholders, information, and constraints before recommending","Wait until change strategy selection to examine vendor effects"],"answer":[2],"why":["Ownership boundaries do not remove consequences of the change.","Approval before impact analysis may create avoidable risk.","Correct: identify interdependencies before recommending a change.","Impact analysis informs the strategy and should precede its selection."],"ref":"BABOK v3 §§6.1–6.3 pp. 103–123; Blueprint p. 2, D4","multi":false,"sourceSet":"ecba-30-timed-practice-set-6.html"},{"id":"q354","domains":[5],"level":1,"tag":"Elicitation preparation","q":"A BA will elicit needs for a new cash-handling procedure. Which preparation is best?","opts":["Choose a workshop and devise questions during the session","Confirm scope, select techniques, and prepare participants, materials, and logistics","Draft the future procedure first for gap review","Withhold the purpose to reduce response bias"],"answer":[1],"why":["A workshop may fit, but its design should be prepared.","Correct: preparation covers scope, technique, participants, materials, and logistics.","A preselected procedure can bias elicitation.","Participants need an appropriate understanding of the purpose."],"ref":"BABOK v3 §4.1 pp. 56–60; Blueprint p. 2, D5","multi":false,"sourceSet":"ecba-30-timed-practice-set-6.html"},{"id":"q355","domains":[5],"level":2,"tag":"Confirming elicitation results","q":"Two stakeholders describe the same approval rule differently. What should the BA do?","opts":["Use the formally senior person's version","Combine both versions into one rule","Record both as approved and let developers resolve them","Review the discrepancy, verify accuracy, and determine whether context explains variation"],"answer":[3],"why":["Authority may resolve a decision but does not establish what was elicited accurately.","Combining conflicting accounts can invent a rule neither intended.","Contradictions should not be approved or delegated to developers.","Correct: confirm accuracy and clarify whether the rule varies by context."],"ref":"BABOK v3 §4.3 pp. 65–66; Blueprint p. 2, D5","multi":false,"sourceSet":"ecba-30-timed-practice-set-6.html"},{"id":"q356","domains":[5],"level":3,"tag":"Prioritizing needs","q":"A high-value requirement depends on a lower-value data-quality capability, and release capacity is limited. What is the best prioritization?","opts":["Rank the high-value item first and defer its dependency","Rank both equally because dependencies prevent comparison","Consider value, risk, urgency, cost, and dependency to agree a feasible sequence","Prioritize the prerequisite alone because it is required"],"answer":[2],"why":["The dependent item may not deliver value without its prerequisite.","Dependencies matter but do not eliminate other prioritization criteria.","Correct: assess multiple factors and dependencies to find a feasible value sequence.","Prerequisite status matters but should not be the sole criterion."],"ref":"BABOK v3 §5.3 pp. 86–90; Blueprint p. 2, D5","multi":false,"sourceSet":"ecba-30-timed-practice-set-6.html"},{"id":"q357","domains":[6],"level":1,"tag":"Verify versus validate","q":"A requirement is clear, testable, and consistent, but users say it will not solve the motivating problem. What is the primary concern?","opts":["Verification of wording","Validation against stakeholder need and outcome","Traceability to design","Formal approval status"],"answer":[1],"why":["The issue is fit to need, not expression quality.","Correct: validation evaluates whether requirements support needs and desired outcomes.","Traceability is useful but does not establish that this is the right problem to solve.","Approval does not prove value or need alignment."],"ref":"BABOK v3 §§7.2–7.3 pp. 141–147; Blueprint p. 3, D6","multi":false,"sourceSet":"ecba-30-timed-practice-set-6.html"},{"id":"q358","domains":[6],"level":2,"tag":"Solution limitations","q":"A solution meets functional requirements but the platform cannot support peak-hour volume. What should the BA assess?","opts":["Effects on value, stakeholders, operations, and feasibility","Whether requirements were approved, then close evaluation","Write a new requirement stating peak volume is supported","Defer it until after implementation"],"answer":[0],"why":["Correct: evaluate the limitation's effect on value and ability to meet needs.","Approval does not prove performance in the operating context.","A requirement cannot create a capability the platform lacks.","Deferral may invalidate the recommendation and creates unassessed risk."],"ref":"BABOK v3 §8.3 pp. 173–176; Blueprint p. 3, D6","multi":false,"sourceSet":"ecba-30-timed-practice-set-6.html"},{"id":"q359","domains":[6],"level":3,"tag":"Option recommendation","q":"Option A promises greater benefit with integration risk; B offers lower benefit with simpler delivery. What is the sound recommendation basis?","opts":["Choose A because expected benefit is highest","Choose B because simplicity is the most reliable value indicator","Choose the option preferred by the largest group","Compare value, costs, feasibility, risks, and stakeholder outcomes and explain trade-offs"],"answer":[3],"why":["Benefit alone does not resolve material integration risk.","Simplicity alone does not establish best value.","Preference matters but should be combined with evidence and impacts.","Correct: compare potential value and relevant costs, risks, feasibility, and stakeholder effects."],"ref":"BABOK v3 §§7.5–7.6 pp. 152–162; Blueprint p. 3, D6","multi":false,"sourceSet":"ecba-30-timed-practice-set-6.html"},{"id":"q360","domains":[7],"level":1,"tag":"Stakeholder identification","q":"A payroll change affects employees, administrators, tax reporting, and a processor. What is the best use of a stakeholder map?","opts":["List only requesters and begin elicitation","Map roles, interests, influence, and impact to identify sources of needs and plan engagement","Map only decision-makers because the sponsor represents others","Schedule communications before assessing stakeholder characteristics"],"answer":[1],"why":["Requesters may not represent every affected group.","Correct: stakeholder mapping supports completeness and engagement planning.","Affected groups may have distinct needs the sponsor cannot represent.","Communication planning should be informed by stakeholder analysis."],"ref":"BABOK v3 §10.43 p. 344; Blueprint p. 3, D7","multi":false,"sourceSet":"ecba-30-timed-practice-set-6.html"},{"id":"q361","domains":[7],"level":2,"tag":"Engagement planning","q":"An expert misses reviews but responds quickly to incidents. How should the BA adapt engagement?","opts":["Escalate missed reviews before changing the plan","Remove the expert and use the manager","Tailor participation to availability while preserving needed input","Send the same package more frequently"],"answer":[2],"why":["Escalation may be premature before identifying barriers.","The expert may hold distinct operational knowledge.","Correct: tailor engagement to availability, contribution, influence, and needs.","More frequency without a format change may add burden but not participation."],"ref":"BABOK v3 §3.2 pp. 31–36; Blueprint p. 3, D7","multi":false,"sourceSet":"ecba-30-timed-practice-set-6.html"},{"id":"q362","domains":[7],"level":3,"tag":"Workshop facilitation","q":"Two senior participants dominate a workshop while quieter staff hold key operational knowledge. What should the facilitator do?","opts":["Let the seniors finish, then ask others to confirm","Restate the goal and use a structured round to hear relevant perspectives","Ask the sponsor whose view should prevail","Split the group and approve both outputs separately"],"answer":[1],"why":["Confirmation after apparent agreement may not surface differing evidence.","Correct: facilitation manages balanced participation toward the stated objective.","Authority does not replace eliciting relevant stakeholder information.","Separate outputs require reconciliation, not automatic independent approval."],"ref":"BABOK v3 §10.50 p. 363; Blueprint p. 3, D7","multi":false,"sourceSet":"ecba-30-timed-practice-set-6.html"},{"id":"q363","domains":[8],"level":1,"tag":"Outcome measures","q":"A service aims to reduce avoidable repeat contacts. Which measure most directly evaluates that outcome?","opts":["Share of users completing service without a repeat contact in a defined period","Number of features delivered","Number of training sessions held","Average ticket closure time regardless of contact reason"],"answer":[0],"why":["Correct: it measures the intended repeat-contact outcome over a defined period.","Feature count measures output, not outcome.","Training count is an implementation activity measure.","Closure time does not directly show whether contacts repeat."],"ref":"BABOK v3 §8.1 p. 166; Blueprint p. 3, D8","multi":false,"sourceSet":"ecba-30-timed-practice-set-6.html"},{"id":"q364","domains":[8],"level":2,"tag":"KPI alignment","q":"Leadership wants timely resolution of urgent cases; the team tracks total cases processed. What should change?","opts":["Keep total cases as KPI because collection is consistent","Set a total-volume target and compare monthly","Define a measure tied to urgent-case timeliness with clear target and interpretation","Replace the metric with a satisfaction survey"],"answer":[2],"why":["Consistency does not make the measure aligned to the objective.","A target does not correct the measure's mismatch.","Correct: align the KPI to the objective and define how to interpret it.","Satisfaction may complement but does not directly replace timeliness measurement."],"ref":"BABOK v3 §10.28 p. 297; Blueprint p. 3, D8","multi":false,"sourceSet":"ecba-30-timed-practice-set-6.html"},{"id":"q365","domains":[8],"level":3,"tag":"Value barriers","q":"Scheduling capacity improves, but managers continue using an informal spreadsheet and customer waits do not fall. What is the best analysis?","opts":["Conclude the solution has no potential value","Examine adoption barriers and actions needed to realize value","Increase the capacity target to make benefits visible","Replace the solution before studying use"],"answer":[1],"why":["Unrealized outcome may reflect a barrier, not absence of potential value.","Correct: identify actions that enable the organization to realize solution value.","Changing the target does not address the usage barrier.","Replacement before diagnosis risks repeating the same issue."],"ref":"BABOK v3 §8.5 pp. 182–186; Blueprint p. 3, D8","multi":false,"sourceSet":"ecba-30-timed-practice-set-6.html"},{"id":"q366","domains":[8],"level":3,"tag":"Measure interpretation","q":"Average response time improves, but the slowest 10% worsen substantially. What conclusion is best?","opts":["The objective is met because the average improved","Exclude outliers because average was agreed","Wait until all cases have identical times","Analyze distribution and affected groups before concluding value was achieved"],"answer":[3],"why":["The average can conceal deterioration for a stakeholder segment.","Excluding affected cases without justification can hide impacts.","Identical times are not necessary to evaluate performance.","Correct: analyze results in context and examine variation and stakeholder impact."],"ref":"BABOK v3 §§8.1–8.2 pp. 166–172; Blueprint p. 3, D8","multi":false,"sourceSet":"ecba-30-timed-practice-set-6.html"},{"id":"q367","domains":[9],"level":1,"tag":"Assumptions and constraints","q":"A rule may prohibit data storage in a cloud region, pending legal review. How should the BA treat this?","opts":["Treat it as confirmed and eliminate the option","Record an assumption, assign validation, and reflect uncertainty in planning","Treat it as risk only after confirmation","Ignore it until design selection"],"answer":[1],"why":["The rule is not confirmed; removing the option may be premature.","Correct: track the unconfirmed condition and validate it while accounting for uncertainty.","The possibility can already affect risk and planning.","Waiting may let work proceed on an invalid assumption."],"ref":"BABOK v3 §3.1 pp. 24–30; Blueprint p. 3, D9","multi":false,"sourceSet":"ecba-30-timed-practice-set-6.html"},{"id":"q368","domains":[9],"level":2,"tag":"Integration context","q":"An order application exchanges data with inventory, finance, and a partner whose interface changes quarterly. What belongs in context analysis?","opts":["Internal boundary only because the partner owns its system","Partner interface only as a testing concern","External systems, data exchanges, ownership, dependencies, and change conditions","The partner change pattern as an internal non-functional requirement"],"answer":[2],"why":["An internal-only boundary omits dependencies.","Testing does not replace early analysis of interfaces and dependencies.","Correct: context includes relevant external systems, exchanges, and conditions.","The partner's release pattern is a contextual dependency, not automatically an internal quality requirement."],"ref":"BABOK v3 §6.1 pp. 103–109; Blueprint p. 3, D9","multi":false,"sourceSet":"ecba-30-timed-practice-set-6.html"},{"id":"q369","domains":[9],"level":3,"tag":"Standards and context","q":"An organization requires documented approval for production changes. An agile team says peer review should suffice. What should the BA recommend?","opts":["Apply the standard as a constraint and tailor the approach to meet it with minimal disruption","Waive it because adaptive delivery supersedes governance","Require a formal board for every backlog item","Document any deviation after release"],"answer":[0],"why":["Correct: tailor work within applicable organizational standards and constraints.","Adaptive delivery does not automatically override governance.","The standard concerns production changes; extending approval to every backlog item may be unnecessary.","Known constraints should be handled during planning, not after deviation."],"ref":"BABOK v3 §3.1 pp. 24–30; Blueprint p. 3, D9","multi":false,"sourceSet":"ecba-30-timed-practice-set-6.html"},{"id":"q370","domains":[9],"level":3,"tag":"Approach adaptation","q":"Interviews repeat answers, but a newly identified operational role has not been represented. What is the best adjustment?","opts":["Continue because repetition proves coverage","Replace all interviews with a survey","Add the role and assess whether targeted elicitation is needed based on its impact and perspective","Use the sponsor as a proxy"],"answer":[2],"why":["Repeated responses do not prove this role's needs are represented.","A survey may not elicit the role's particular perspective and need not replace all interviews.","Correct: adapt the approach to the identified stakeholder gap and remaining need.","A sponsor may not have the operational perspective needed to substitute for the role."],"ref":"BABOK v3 §3.1 pp. 24–30; Blueprint p. 3, D9","multi":false,"sourceSet":"ecba-30-timed-practice-set-6.html"},{"id":"q371","domains":[1],"level":1,"tag":"","q":"A regional insurer meets its claim-processing target, yet customers still call repeatedly to ask what happens next. What should the BA clarify first?","opts":["The business need and desired stakeholder outcome behind the call-reduction target","The solution feature most likely to reduce incoming calls","The implementation metric used to measure processing speed","The operational owner responsible for the current call queue"],"answer":[0],"why":["Correct: clarify the need and intended outcome before selecting a solution or proxy measure.","This selects a feature before the underlying need is understood.","Processing speed is an output measure and may not address customer uncertainty.","Ownership matters, but it does not establish the need or expected outcome."],"ref":"BABOK v3 §§2.1–2.2 pp. 12–14; Blueprint p. 2, Domain 1","multi":false,"sourceSet":"ecba-40-timed-practice-set-7.html"},{"id":"q372","domains":[1],"level":2,"tag":"","q":"A logistics firm asks for a mobile feature, but interviews show dispatchers need to reassign routes during severe weather. Which requirement statement is at the most appropriate level?","opts":["The mobile screen shall display an orange reassignment control","Dispatchers need to maintain safe, feasible deliveries when route conditions change","The solution shall use the company’s approved mobile framework","Route reassignment shall complete within three seconds"],"answer":[1],"why":["This specifies a design element before validating the underlying need.","Correct: this expresses a stakeholder need without prematurely fixing a particular solution.","This is an implementation constraint, not the stakeholder need.","This is a solution quality requirement and does not express the broader need."],"ref":"BABOK v3 §2.3 p. 16; Blueprint p. 2, Domain 1","multi":false,"sourceSet":"ecba-40-timed-practice-set-7.html"},{"id":"q373","domains":[1],"level":2,"tag":"","q":"A lending platform must calculate monthly payments, retain an audit trail for seven years, and convert active applications at launch. How should these be classified, in order?","opts":["Business; transition; non-functional","Stakeholder; solution functional; business","Solution functional; solution non-functional; transition","Solution non-functional; business; stakeholder"],"answer":[2],"why":["The payment calculation is solution behavior, retention is a quality/compliance constraint, and conversion supports transition.","The classifications confuse levels and do not fit the three statements.","Correct: calculation is functional, retention is non-functional, and conversion is a transition requirement.","This reverses the functional and non-functional distinction and misclassifies conversion."],"ref":"BABOK v3 §2.3 p. 16; Blueprint p. 2, Domain 1","multi":false,"sourceSet":"ecba-40-timed-practice-set-7.html"},{"id":"q374","domains":[1],"level":3,"tag":"","q":"A prototype for a hospital discharge workflow reveals pharmacists need to flag interactions before a prescription is released. The approved scope covers discharge summaries only. What is the best BA response?","opts":["Treat the flag as a design detail because it emerged during prototyping","Add the capability to scope because the prototype demonstrated it","Reject the finding because the approved scope is the controlling baseline","Analyze the need and its value, impacts, and relationship to scope before deciding how to manage it"],"answer":[3],"why":["A newly discovered need is not automatically only a design detail.","Evidence from a prototype does not itself authorize a scope expansion.","A baseline guides control but does not justify ignoring relevant new information.","Correct: analyze the requirement and its implications, then use the applicable change or governance process."],"ref":"BABOK v3 §2.4 p. 19; Blueprint p. 2, Domain 1","multi":false,"sourceSet":"ecba-40-timed-practice-set-7.html"},{"id":"q375","domains":[1],"level":3,"tag":"","q":"A bank delivers a fraud alert feature on time. Alerts increase, but losses are unchanged and legitimate transactions are delayed. Which conclusion is most defensible?","opts":["The change created value because the planned feature was delivered","The change failed because the loss measure did not improve","Value is mixed or unproven; assess outcomes across affected stakeholders and the context before concluding","The solution is successful if alert volume meets its acceptance criteria"],"answer":[2],"why":["Delivery of a feature is not evidence that stakeholder value was achieved.","One unchanged outcome does not by itself establish overall failure; delays also need analysis.","Correct: evaluate value in context across intended and unintended outcomes and affected stakeholders.","Acceptance criteria can confirm delivery quality but not establish business value on their own."],"ref":"BABOK v3 §§2.1–2.4 pp. 12–19; Blueprint p. 2, Domain 1","multi":false,"sourceSet":"ecba-40-timed-practice-set-7.html"},{"id":"q376","domains":[2],"level":1,"tag":"","q":"A dashboard shows improved average response time, but complaints rise sharply among users with assistive technology. What should the BA do first?","opts":["Report the average and handle accessibility as a separate release","Investigate the subgroup impact and make the conflicting evidence visible to decision-makers","Recommend the change because the overall KPI improved","Ask the sponsor whether the complaints should be included in the analysis"],"answer":[1],"why":["Averages can conceal material impacts and should not displace the subgroup evidence.","Correct: ethical, evidence-based analysis makes relevant stakeholder impacts visible.","One improved KPI does not resolve accessibility concerns or unintended harm.","The BA should not wait for permission to record relevant evidence."],"ref":"BABOK v3 Chapter 9 pp. 188–216; Blueprint p. 5, Domain 2","multi":false,"sourceSet":"ecba-40-timed-practice-set-7.html"},{"id":"q377","domains":[2],"level":2,"tag":"","q":"Two executives use the same word, “urgent,” to mean different service deadlines. What is the best analyst behavior?","opts":["Use the executive sponsor’s definition for consistency","Choose the stricter definition to reduce delivery risk","Record both definitions as synonyms and continue elicitation","Ask for examples and clarify the operational meaning before modeling the rule"],"answer":[3],"why":["Seniority does not resolve an ambiguous term shared across stakeholders.","A stricter rule may create unnecessary cost or conflict with actual policy.","Different meanings should not be treated as equivalent.","Correct: curiosity and precise communication clarify shared meaning before analysis proceeds."],"ref":"BABOK v3 Chapter 9 pp. 188–216; Blueprint p. 5, Domain 2","multi":false,"sourceSet":"ecba-40-timed-practice-set-7.html"},{"id":"q378","domains":[2],"level":2,"tag":"","q":"A proposed warehouse change lowers picking time but increases replenishment errors and overtime in another facility. Which mindset should guide the analysis?","opts":["Optimize the warehouse that owns the initiative","Treat the second facility’s result as an external operational issue","Examine the interactions and downstream effects across the broader system","Keep the original measure and investigate only if it misses target"],"answer":[2],"why":["Optimizing one unit can transfer cost or risk elsewhere.","The second-facility effects may be caused by the change and are relevant.","Correct: systems thinking considers relationships and consequences across connected parts.","Known effects warrant analysis before they become a target failure."],"ref":"BABOK v3 Chapter 9 pp. 188–216; Blueprint p. 5, Domain 2","multi":false,"sourceSet":"ecba-40-timed-practice-set-7.html"},{"id":"q379","domains":[2],"level":3,"tag":"","q":"A BA’s initial model is challenged by evidence from a frontline team. The sponsor expects the BA to defend the original recommendation. What is the most professional response?","opts":["Reassess the evidence, assumptions, and implications, then explain any change to the recommendation","Retain the recommendation until the sponsor formally changes the mandate","Replace the recommendation immediately with the frontline team’s preferred option","Remove the conflicting evidence from the model because it is not aligned to the original scope"],"answer":[0],"why":["Correct: accountability includes revisiting assumptions and communicating evidence-based changes.","A mandate does not make a recommendation immune to new evidence.","New evidence should be assessed; preference alone does not establish the best option.","Relevant evidence should not be omitted merely because it challenges an earlier view."],"ref":"BABOK v3 Chapter 9 pp. 188–216; Blueprint p. 5, Domain 2","multi":false,"sourceSet":"ecba-40-timed-practice-set-7.html"},{"id":"q380","domains":[2],"level":3,"tag":"","q":"A vendor offers a proprietary scoring model. It improves throughput, but the team cannot explain why some applicants are rejected. Which response best reflects a BA mindset?","opts":["Accept the model if the vendor meets the contract’s accuracy target","Treat explainability as a technical detail and recommend based on throughput","Ask the vendor to document its method after rollout","Assess ethical and stakeholder implications, transparency needs, and risks before recommending the option"],"answer":[3],"why":["Contract performance does not alone address fairness, accountability, or stakeholder impacts.","Explainability can affect trust, compliance, and stakeholder outcomes, so it is not merely technical.","Deferring transparency may prevent responsible evaluation before adoption.","Correct: examine value alongside ethical implications, risks, and stakeholder needs."],"ref":"BABOK v3 Chapter 9 pp. 188–216; Blueprint p. 5, Domain 2","multi":false,"sourceSet":"ecba-40-timed-practice-set-7.html"},{"id":"q381","domains":[3],"level":1,"tag":"","q":"A company has a fixed legal migration date but is uncertain which self-service features customers will adopt. How should the BA approach the work?","opts":["Use one predictive approach because the deadline is fixed","Use one adaptive approach because feature adoption is uncertain","Tailor practices to each workstream and coordinate shared dependencies","Delay approach selection until feature requirements are fully known"],"answer":[2],"why":["A fixed date does not mean every workstream has stable requirements.","Uncertainty in features does not eliminate the need to plan the fixed migration.","Correct: tailor the approach to the characteristics of each part and coordinate dependencies.","Approach planning should help manage uncertainty, not wait for it to disappear."],"ref":"BABOK v3 §3.1 pp. 24–30; Blueprint p. 2, Domain 3","multi":false,"sourceSet":"ecba-40-timed-practice-set-7.html"},{"id":"q382","domains":[3],"level":2,"tag":"","q":"The product owner prioritizes features; a regulator’s delegate approves evidence retention. A feature changes retention behavior and competes for a release slot. How should the BA structure decisions?","opts":["Ask the product owner to decide both priority and retention because the release is product-led","Separate the retention compliance decision from product prioritization, then make their dependency explicit","Ask the regulator’s delegate to rank the entire product backlog","Escalate both decisions to the steering committee to avoid role ambiguity"],"answer":[1],"why":["Product ownership does not automatically confer authority over regulatory interpretation.","Correct: respect distinct decision rights and explicitly coordinate their effects on release decisions.","The delegate’s authority is limited to retention evidence, not necessarily product value ranking.","Governance should be followed; escalation is unnecessary if roles are defined."],"ref":"BABOK v3 §§3.2–3.3 pp. 31–41; Blueprint p. 2, Domain 3","multi":false,"sourceSet":"ecba-40-timed-practice-set-7.html"},{"id":"q383","domains":[3],"level":3,"tag":"","q":"A program uses iterative delivery, but auditors require traceability from each control to evidence and approval. Teams say detailed traceability slows learning. What is the best recommendation?","opts":["Tailor traceability to provide required control evidence while keeping links lightweight and iterative","Apply a full document-driven lifecycle because auditability and iteration are incompatible","Keep traceability informal until an audit identifies a gap","Move audit approval to the end so teams can maintain delivery speed"],"answer":[0],"why":["Correct: tailor the approach to satisfy governance while preserving fit-for-context iterative practices.","Auditability and iterative delivery can coexist; a full predictive lifecycle is not automatically required.","Known control needs should be addressed in the approach, not after a failure.","Deferring approval may create compliance and rework risks."],"ref":"BABOK v3 §§3.1–3.3 pp. 24–41; Blueprint p. 2, Domain 3","multi":false,"sourceSet":"ecba-40-timed-practice-set-7.html"},{"id":"q384","domains":[4],"level":1,"tag":"","q":"A retailer says refunds take a week. System data show most take one day, but a small group waits over ten days. What should current-state analysis do next?","opts":["Use the average as the current state and set the same future target","Validate data definitions and segment cases to understand the long delays","Use customer reports instead of system data","Begin redesigning the refund process around the one-day majority"],"answer":[1],"why":["An average can conceal the very problem described; it is not automatically a target.","Correct: validate the measures and investigate variation and the affected cases.","Both sources can be useful and should be reconciled rather than replaced.","Redesign before understanding causes may fail to address the long-delay segment."],"ref":"BABOK v3 §6.1 pp. 103–109; Blueprint p. 2, Domain 4","multi":false,"sourceSet":"ecba-40-timed-practice-set-7.html"},{"id":"q385","domains":[4],"level":2,"tag":"","q":"A city wants fewer missed waste collections, but departments disagree whether the future state requires route optimization or better exception handling. What should be agreed before solution selection?","opts":["A route optimization design with a configurable exception queue","A vendor shortlist that can support both capabilities","The desired outcomes, capabilities, boundaries, and measures for the future state","A feature backlog ranked by each department’s preferred option"],"answer":[2],"why":["This combines two possible solution features before the future-state need is agreed.","Vendor selection is premature while outcomes and boundaries remain unclear.","Correct: define the future-state outcomes and capabilities before comparing solution options.","Ranking preferred features does not resolve the shared target state."],"ref":"BABOK v3 §6.2 pp. 110–119; Blueprint p. 2, Domain 4","multi":false,"sourceSet":"ecba-40-timed-practice-set-7.html"},{"id":"q386","domains":[4],"level":2,"tag":"","q":"A new supplier portal could reduce manual entry, but suppliers have uneven connectivity and orders must continue during outages. What is the best treatment?","opts":["Record connectivity as an implementation issue and proceed with the preferred portal","Reject the portal because any connectivity risk makes it infeasible","Require continuous availability and treat the risk as resolved by that requirement","Analyze likelihood and impact, identify response options, and assess residual risk against expected value"],"answer":[3],"why":["Connectivity can affect adoption and business continuity, not just implementation details.","A risk does not automatically make an option infeasible; responses may be available.","A requirement does not eliminate the underlying risk or prove feasibility.","Correct: assess risk and responses, then consider remaining exposure against value."],"ref":"BABOK v3 §6.3 pp. 120–123; Blueprint p. 2, Domain 4","multi":false,"sourceSet":"ecba-40-timed-practice-set-7.html"},{"id":"q387","domains":[4],"level":3,"tag":"","q":"An acquisition must unify customer records in six months. The target company has undocumented processes and a union consultation period. Which change strategy is strongest?","opts":["Plan a single cutover at month six and add consultation as a communication task","Set a phased transition with discovery, consultation, data controls, readiness criteria, and contingency points","Begin data conversion immediately while process details are documented in parallel","Delay all planning until the target company’s processes are fully documented"],"answer":[1],"why":["A date-only strategy leaves readiness, data, and consultation dependencies unmanaged.","Correct: a viable change strategy addresses transition, stakeholders, constraints, readiness, and contingencies.","Early conversion may create control and rework risks before the processes are understood.","Planning can proceed with uncertainty explicitly managed; complete documentation is not a prerequisite."],"ref":"BABOK v3 §6.4 pp. 124–130; Blueprint p. 2, Domain 4","multi":false,"sourceSet":"ecba-40-timed-practice-set-7.html"},{"id":"q388","domains":[5],"level":1,"tag":"","q":"A BA must understand why emergency-room discharge instructions are often misunderstood. Which elicitation preparation is most appropriate?","opts":["Define the question scope, identify relevant patient and staff perspectives, and select suitable techniques","Prepare a staff survey only because all patients receive the same instructions","Draft revised instructions and use interviews to validate the wording","Ask the department head for a representative account and confirm it with clinicians"],"answer":[0],"why":["Correct: prepare scope, stakeholder sources, and techniques appropriate to the need.","A survey may miss context and may not suit every perspective or sensitive situation.","This presumes the solution before understanding causes of misunderstanding.","A department head cannot necessarily substitute for distinct patient and staff experiences."],"ref":"BABOK v3 §4.1 pp. 56–60; Blueprint p. 2, Domain 5","multi":false,"sourceSet":"ecba-40-timed-practice-set-7.html"},{"id":"q389","domains":[5],"level":2,"tag":"","q":"Operations and compliance provide conflicting interpretations of a reporting rule. What is the best confirmation step?","opts":["Adopt compliance’s interpretation because it has regulatory authority","Combine the interpretations into one rule with both conditions","Trace the disagreement to its source, validate examples, and determine whether distinct contexts or a decision are involved","Record both interpretations as approved pending implementation testing"],"answer":[2],"why":["Authority may decide a policy question but first the conflict and evidence should be understood.","Combining rules can create a requirement neither group intended.","Correct: confirm accuracy and context, then identify whether a decision is needed.","Contradictory statements are not confirmed requirements and should not be left to testing."],"ref":"BABOK v3 §4.3 pp. 65–66; Blueprint p. 2, Domain 5","multi":false,"sourceSet":"ecba-40-timed-practice-set-7.html"},{"id":"q390","domains":[5],"level":3,"tag":"","q":"A safety requirement is high value but depends on a data migration that is uncertain. A lower-value reporting feature is independent. Capacity fits only one. How should the BA support prioritization?","opts":["Select the safety requirement because value outweighs delivery uncertainty","Select the reporting feature because it can be completed with certainty","Treat both as equal until migration certainty improves","Compare value, urgency, risk, dependency, and feasibility with stakeholders, including sequencing or de-scoping options"],"answer":[3],"why":["High value matters, but feasibility and dependency risks affect achievable value.","Certainty alone should not displace safety value and urgency.","Uncertainty calls for informed comparison, not automatic equal ranking.","Correct: weigh the relevant factors and work with stakeholders on a feasible sequence or scope choice."],"ref":"BABOK v3 §5.3 pp. 86–90; Blueprint p. 2, Domain 5","multi":false,"sourceSet":"ecba-40-timed-practice-set-7.html"},{"id":"q391","domains":[5],"level":3,"tag":"","q":"A regulator changes a reporting rule after requirements are approved. The requested update affects a shared data definition and two designs already in build. What should the BA do first?","opts":["Assess the change’s value, impacts, dependencies, and conflicts against the current requirements and designs","Update the requirement and notify the teams because the regulator is authoritative","Reject the change because the requirements have already been approved","Ask the delivery teams to estimate the change before analyzing its effect on other requirements"],"answer":[0],"why":["Correct: assess implications, value, and conflicts across related requirements and designs before deciding how to proceed.","Authority explains why the change matters, but analysis and impact assessment are still required.","Approval does not make requirements immune to changes in context or regulation.","Estimation may be part of impact analysis, but examining only delivery effort misses semantic and cross-design effects."],"ref":"BABOK v3 §5.4 pp. 91–94; Blueprint p. 2, Domain 5","multi":false,"sourceSet":"ecba-40-timed-practice-set-7.html"},{"id":"q392","domains":[6],"level":1,"tag":"","q":"A requirement is unambiguous and testable, yet users say it will not solve the reason the change was funded. Which review is most needed?","opts":["Verification of requirement form","Validation against stakeholder need and intended outcome","Traceability to the approved design","Approval by the solution owner"],"answer":[1],"why":["The stated problem is relevance, not clarity or testability.","Correct: validation determines whether requirements support stakeholder needs and outcomes.","Traceability shows relationships but does not prove the right need is addressed.","Approval alone does not establish fit to need."],"ref":"BABOK v3 §7.2–7.3 pp. 141–147; Blueprint p. 3, Domain 6","multi":false,"sourceSet":"ecba-40-timed-practice-set-7.html"},{"id":"q393","domains":[6],"level":2,"tag":"","q":"Two options meet mandatory requirements. A has lower operating cost but high integration risk; B costs more but preserves a proven interface. What should the recommendation compare?","opts":["Potential value, lifecycle cost, feasibility, integration risk, and stakeholder impact","Initial cost and implementation duration, then select the lower combination","Stakeholder preference and vendor confidence, then select the most supported option","Mandatory compliance and feature coverage, then treat integration risk as delivery-only"],"answer":[0],"why":["Correct: compare value and relevant cost, feasibility, risk, and stakeholder effects.","Initial cost and duration omit lifecycle effects and material integration risk.","Preference and confidence are relevant but insufficient without comparative evidence.","Integration risk can affect feasibility and value, not just delivery management."],"ref":"BABOK v3 §§7.5–7.6 pp. 152–162; Blueprint p. 3, Domain 6","multi":false,"sourceSet":"ecba-40-timed-practice-set-7.html"},{"id":"q394","domains":[6],"level":2,"tag":"","q":"A scheduling solution meets the documented rules but cannot handle seasonal volume without manual workarounds. What should solution evaluation examine?","opts":["Whether users followed the rules before assessing the platform","Whether the workaround can be documented as an acceptable operating procedure","The limitation’s effect on value, operations, stakeholders, and feasible response options","Whether the rules should be relaxed to match the platform’s capacity"],"answer":[2],"why":["User compliance does not resolve the solution's capacity limitation.","Documenting a workaround does not establish its cost, risk, or acceptability.","Correct: assess limitations and their impact, then evaluate suitable actions.","Relaxing requirements may undermine the original need and should not be the default response."],"ref":"BABOK v3 §8.3 pp. 173–176; Blueprint p. 3, Domain 6","multi":false,"sourceSet":"ecba-40-timed-practice-set-7.html"},{"id":"q395","domains":[6],"level":3,"tag":"","q":"A pilot meets usability targets, but frontline staff bypass the solution during peak periods because it slows a critical handoff. What is the best conclusion?","opts":["The usability requirement is verified, so the solution is acceptable","The solution is validated because users completed the pilot tasks","The pilot should be repeated with the same measures to confirm the result","The solution may not satisfy needs in its operating context; investigate peak workflow and stakeholder outcomes"],"answer":[3],"why":["Meeting one target does not establish acceptability across operating conditions.","Completing pilot tasks does not demonstrate that the solution works in the critical handoff context.","Repeating unchanged measures may reproduce the blind spot rather than explain it.","Correct: validate solution performance against needs and context, including observed workarounds."],"ref":"BABOK v3 §7.3 p. 144; Blueprint p. 3, Domain 6","multi":false,"sourceSet":"ecba-40-timed-practice-set-7.html"},{"id":"q396","domains":[6],"level":3,"tag":"","q":"A vendor option promises the largest benefit, but its benefit estimate assumes 95% adoption; comparable deployments reached 60–70%. What is the strongest recommendation approach?","opts":["Use the vendor estimate because it is specific to this solution","Re-estimate value using credible adoption scenarios, compare options and risks, and state assumptions","Reject the option because the adoption estimate is above historical results","Recommend the option with the lowest forecast variance"],"answer":[1],"why":["Specificity does not make an assumption credible or validated.","Correct: test assumptions with evidence and compare potential value under plausible scenarios.","Historical results inform analysis but do not prove the option cannot achieve higher adoption.","Forecast variance is only one consideration and does not establish value."],"ref":"BABOK v3 §§7.5–7.6 pp. 152–162; Blueprint p. 3, Domain 6","multi":false,"sourceSet":"ecba-40-timed-practice-set-7.html"},{"id":"q397","domains":[7],"level":1,"tag":"","q":"A new benefits platform affects retirees, HR, payroll, a regulator, and a processing partner. What is the best first stakeholder action?","opts":["Start with the sponsor’s contacts and add others if they raise concerns","Identify stakeholders and analyze their interests, influence, impacts, and information needs","Invite every group to the first workshop and let participants define representation","Map decision-makers first and treat other affected groups as represented by them"],"answer":[1],"why":["Sponsor contacts may omit affected groups or sources of requirements.","Correct: identify and analyze relevant stakeholders to guide engagement and elicitation.","A broad workshop without stakeholder analysis may be ineffective and miss appropriate representation.","Decision authority does not imply that others’ needs are represented."],"ref":"BABOK v3 §10.43 p. 344; Blueprint p. 3, Domain 7","multi":false,"sourceSet":"ecba-40-timed-practice-set-7.html"},{"id":"q398","domains":[7],"level":2,"tag":"","q":"A remote operations lead has essential process knowledge but cannot attend daytime sessions. What adjustment best supports engagement?","opts":["Proceed with available managers and ask them to validate the lead’s input","Send the lead the meeting notes and request approval","Use an asynchronous or alternate-time elicitation method and confirm the lead’s contribution directly","Remove the lead from the stakeholder group if attendance is not possible"],"answer":[2],"why":["Managers may not hold the same firsthand process knowledge.","Reviewing notes is not equivalent to eliciting the lead's perspective.","Correct: tailor the engagement method while preserving direct input from the relevant stakeholder.","Availability constraints do not remove the stakeholder's relevance."],"ref":"BABOK v3 §3.2 pp. 31–36; Blueprint p. 3, Domain 7","multi":false,"sourceSet":"ecba-40-timed-practice-set-7.html"},{"id":"q399","domains":[7],"level":2,"tag":"","q":"A workshop must resolve conflicting definitions of “active customer” across sales, finance, and analytics. Which design is most effective?","opts":["Ask each function to submit its definition, then select the most frequently used","Have the sponsor state the preferred definition before discussion","Let each group create a model independently and merge them after the workshop","Set a shared objective, compare examples and consequences, and record an agreed definition or unresolved decision"],"answer":[3],"why":["Frequency does not resolve differing business meanings or consequences.","A preferred definition can bias analysis before relevant perspectives are heard.","Separate models may deepen inconsistency and make reconciliation harder.","Correct: a facilitated workshop should produce a defined work product and make unresolved decisions explicit."],"ref":"BABOK v3 §10.50 p. 363; Blueprint p. 3, Domain 7","multi":false,"sourceSet":"ecba-40-timed-practice-set-7.html"},{"id":"q400","domains":[7],"level":3,"tag":"","q":"A department head supports a change publicly but privately directs staff to keep using the legacy process. What should the BA do?","opts":["Explore the head’s concerns and incentives, clarify impacts, and plan an appropriate conversation with the relevant stakeholders","Record the head as resistant and escalate directly to the sponsor","Treat public support as sufficient and proceed with rollout communication","Ask the staff to follow the new process and avoid involving the department head"],"answer":[0],"why":["Correct: understand stakeholder motivations and concerns, then address collaboration barriers appropriately.","Labeling and escalation before understanding the concern may worsen the conflict.","Public endorsement does not resolve behavior that blocks adoption.","Bypassing the head may increase resistance and leave the cause unaddressed."],"ref":"BABOK v3 §4.5 pp. 71–75; Blueprint p. 3, Domain 7","multi":false,"sourceSet":"ecba-40-timed-practice-set-7.html"},{"id":"q401","domains":[7],"level":3,"tag":"","q":"A regulator, product team, and customer advocates disagree on acceptable identity verification. The regulator sets minimum controls; advocates report exclusion; product warns of abandonment. How should the BA facilitate resolution?","opts":["Use the minimum regulatory control as the sole requirement and treat other concerns as optional","Clarify decision authority and constraints, compare evidence and impacts, and facilitate an explicit trade-off decision","Use customer preference as the deciding factor because value is customer-defined","Ask the product team to select the option that minimizes abandonment"],"answer":[1],"why":["Minimum compliance is a constraint but does not resolve other stakeholder outcomes or options.","Correct: surface constraints, authority, evidence, and impacts, then make the trade-off explicit through governance.","Customer value matters, but it cannot override regulatory constraints or other affected needs.","Product metrics are relevant but insufficient to decide a multi-stakeholder trade-off."],"ref":"BABOK v3 §§3.2, 4.5 pp. 31–36, 71–75; Blueprint p. 3, Domain 7","multi":false,"sourceSet":"ecba-40-timed-practice-set-7.html"},{"id":"q402","domains":[8],"level":1,"tag":"","q":"A redesign aims to reduce repeat visits for a licensing service. Which measure most directly tests the outcome?","opts":["Share of applicants completing the process without an avoidable repeat visit within a defined period","Number of screens removed from the redesigned application","Number of staff trained before launch","Average time spent on the application regardless of completion"],"answer":[0],"why":["Correct: it measures the intended outcome and defines the observation window.","Screen count measures a design change, not the user outcome.","Training measures readiness activity, not fewer repeat visits.","Time spent may be useful but does not directly measure repeat visits or completion."],"ref":"BABOK v3 §8.1 p. 166; Blueprint p. 3, Domain 8","multi":false,"sourceSet":"ecba-40-timed-practice-set-7.html"},{"id":"q403","domains":[8],"level":2,"tag":"","q":"The board objective is to reduce preventable service failures. The dashboard tracks tickets closed per agent. What is the strongest improvement?","opts":["Keep closures per agent and increase the target","Replace the KPI with customer satisfaction alone","Define measures that indicate preventable failure rates and customer impact, with clear baselines and targets","Use average handling time because it is consistently available"],"answer":[2],"why":["A higher volume target may reward speed without reducing failures.","Satisfaction can complement but may not directly identify preventable failure.","Correct: align measures to the strategic objective and make baselines and targets interpretable.","Handling time is not a direct indicator of preventable failure and can create adverse incentives."],"ref":"BABOK v3 §10.28 p. 297; Blueprint p. 3, Domain 8","multi":false,"sourceSet":"ecba-40-timed-practice-set-7.html"},{"id":"q404","domains":[8],"level":2,"tag":"","q":"A pilot reduces average onboarding time by 20%, but failure rates rise for international customers and fall for domestic customers. What should the BA report?","opts":["The target was met because the overall mean improved","The result is positive but mixed; analyze segment outcomes and causes before judging value","The pilot failed because any segment worsened","Exclude international cases because they are a small proportion"],"answer":[1],"why":["The mean hides materially different subgroup outcomes.","Correct: analyze the distribution and causes before concluding value across stakeholders.","A worsened segment is important but does not alone characterize all outcomes or options.","A smaller group can still experience material impact and should not be omitted without justification."],"ref":"BABOK v3 §§8.1–8.2 pp. 166–172; Blueprint p. 3, Domain 8","multi":false,"sourceSet":"ecba-40-timed-practice-set-7.html"},{"id":"q405","domains":[8],"level":3,"tag":"","q":"A new self-service capability is technically available, but only 18% of eligible customers use it. The business case assumes 65% adoption. What should the BA recommend?","opts":["Reforecast value using observed adoption and investigate barriers before deciding on further action","Keep the business case unchanged until a full year of usage data exists","Increase promotion immediately and retain the 65% assumption","Conclude the solution failed and begin replacement selection"],"answer":[0],"why":["Correct: use evidence to reassess realized value and identify barriers that may be addressable.","Waiting may prolong a material value gap when current evidence is already informative.","Promotion may help but should follow barrier analysis; the assumption needs review.","Low adoption signals a problem but does not prove replacement is the best response."],"ref":"BABOK v3 §8.5 pp. 182–186; Blueprint p. 3, Domain 8","multi":false,"sourceSet":"ecba-40-timed-practice-set-7.html"},{"id":"q406","domains":[9],"level":1,"tag":"","q":"A proposed customer-data platform may conflict with a new residency rule, and legal interpretation is pending. How should the BA handle it?","opts":["Treat the rule as confirmed and remove the platform option","Track the interpretation as an assumption or risk, assign validation, and reflect uncertainty in decisions","Ignore the possible conflict until legal issues a final opinion","Record it as a non-functional requirement and proceed with design"],"answer":[1],"why":["An unconfirmed interpretation should not prematurely eliminate an option.","Correct: identify uncertainty, ownership, validation timing, and decision implications.","The possibility can already affect options, planning, and risk.","The rule may constrain the solution, but classification and feasibility need validation."],"ref":"BABOK v3 §3.1 pp. 24–30; Blueprint p. 3, Domain 9","multi":false,"sourceSet":"ecba-40-timed-practice-set-7.html"},{"id":"q407","domains":[9],"level":2,"tag":"","q":"A retailer’s checkout depends on inventory, fraud screening, payment providers, and a tax service with separate release calendars. What should context analysis emphasize?","opts":["The retailer’s checkout boundary and internal requirements only","The vendor contracts because technical interfaces can be tested later","The interfaces and data flows only, leaving release timing to project planning","External dependencies, ownership, data exchanges, constraints, and release conditions that affect the change"],"answer":[3],"why":["An internal-only boundary omits conditions that can prevent end-to-end value.","Testing cannot replace early analysis of operational and integration dependencies.","Release timing is part of context when it constrains integration and delivery.","Correct: analyze the relevant environment and interdependencies affecting the solution."],"ref":"BABOK v3 §6.1 pp. 103–109; Blueprint p. 3, Domain 9","multi":false,"sourceSet":"ecba-40-timed-practice-set-7.html"},{"id":"q408","domains":[9],"level":2,"tag":"","q":"The organization requires dual approval for high-risk payments. A new product team proposes a single-click flow, arguing that usability testing favors it. What should the BA do?","opts":["Accept the usability evidence and defer the control to operations","Treat dual approval as a constraint, then assess compliant designs and usability trade-offs","Retain dual approval exactly as implemented today without considering alternatives","Ask users to choose between control and usability"],"answer":[1],"why":["Usability evidence does not authorize removing an organizational control.","Correct: recognize constraints and evaluate solution options that meet them while considering usability.","The control may be mandatory, but its implementation could still be improved.","Users cannot decide whether a required control applies."],"ref":"BABOK v3 §3.1 pp. 24–30; Blueprint p. 3, Domain 9","multi":false,"sourceSet":"ecba-40-timed-practice-set-7.html"},{"id":"q409","domains":[9],"level":3,"tag":"","q":"A solution meets local operating needs but cannot exchange records with the enterprise identity service required by corporate policy. Which limitation is most relevant?","opts":["A solution limitation, because the product lacks an interface","An enterprise limitation, because the organization lacks identity governance","A context constraint, because corporate policy and shared services shape feasible solution design","A stakeholder limitation, because local users did not request integration"],"answer":[2],"why":["The technical gap matters, but the question centers on a policy and enterprise service constraint.","Identity governance exists; the problem is the solution's fit with it.","Correct: enterprise context and policy constrain what solution options are feasible.","The absence of a local request does not remove enterprise requirements."],"ref":"BABOK v3 §8.4 pp. 177–181; Blueprint p. 3, Domain 9","multi":false,"sourceSet":"ecba-40-timed-practice-set-7.html"},{"id":"q410","domains":[9],"level":3,"tag":"","q":"A merger program must comply with two national privacy regimes, preserve service continuity, and integrate systems before a regulator’s deadline. Which planning response is strongest?","opts":["Use one standard migration plan and document jurisdictional exceptions during execution","Prioritize the regulator deadline and resolve continuity and privacy conflicts as they arise","Decompose the initiative by jurisdiction and system, then reconcile dependencies, constraints, decision rights, and transition risks in an integrated approach","Wait for each local legal team to complete its analysis before building any program plan"],"answer":[2],"why":["A single plan without early constraint analysis may create avoidable compliance and continuity risks.","Deferring known conflicts risks a late infeasible plan.","Correct: analyze context and dependencies across jurisdictions while maintaining an integrated transition approach.","Local input is essential, but planning can proceed with uncertainty and validation tracked explicitly."],"ref":"BABOK v3 §§3.1, 6.1 pp. 24–30, 103–109; Blueprint p. 3, Domain 9","multi":false,"sourceSet":"ecba-40-timed-practice-set-7.html"},{"id":"q411","domains":[1],"level":1,"tag":"","q":"A regional insurer meets its claim-processing SLA, but customers still call repeatedly because they cannot tell whether documents are missing. The sponsor asks for a chatbot. What should the BA establish first?","opts":["Clarify the underlying need and desired customer outcome before comparing response options","Translate the chatbot request into a solution requirement and confirm its acceptance criteria","Set a lower call-volume target and identify the solution likely to meet it","Confirm the processing SLA and treat repeat calls as a separate service issue"],"answer":[0],"why":["Correct: understand the need and intended value before committing to a proposed solution.","The requested chatbot may be an option, but it should not be treated as the validated need.","Call volume is an indicator, not necessarily the desired stakeholder outcome or root need.","The repeat calls may be directly related to the change and should be analyzed in context."],"ref":"BABOK v3 §§2.1–2.2 pp. 12–14; Blueprint p. 2, Domain 1","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q412","domains":[1],"level":2,"tag":"","q":"A freight operator wants a mobile capability so dispatchers can reassign routes during severe weather. Which statement best expresses the stakeholder requirement?","opts":["The application shall provide a route-reassignment button on the dispatch screen","Dispatchers need to reassign routes during severe weather so affected deliveries can be managed.","The application shall reassign each affected vehicle within three seconds","The solution shall use the enterprise-approved mobile technology stack"],"answer":[1],"why":["This prescribes a specific interface before confirming the need.","Correct: expresses the stakeholder need without prescribing an interface, response time, or technology.","This is a performance quality requirement, not the broader stakeholder need.","This is an implementation constraint and does not express the stakeholder outcome."],"ref":"BABOK v3 §2.3 p. 16; Blueprint p. 2, Domain 1","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"},{"id":"q413","domains":[1],"level":3,"tag":"","q":"A lender needs automated monthly payment calculations, seven-year audit retention, and temporary conversion of open applications at launch. Which sequence classifies these accurately?","opts":["Business requirement; transition requirement; non-functional requirement","Stakeholder requirement; functional requirement; business requirement","Functional requirement; non-functional requirement; transition requirement","Non-functional requirement; stakeholder requirement; solution functional requirement"],"answer":[2],"why":["The calculation is solution behavior; retention is a quality/compliance constraint; conversion is temporary transition capability.","This mixes levels and does not correctly classify the examples.","Correct: calculations describe solution behavior, retention is a quality/compliance constraint, and conversion is temporary transition capability.","This reverses the first two categories and misclassifies conversion."],"ref":"BABOK v3 §§2.3–2.4 pp. 16, 19; Blueprint p. 2, Domain 1","multi":false,"sourceSet":"ecba-50-timed-practice-set-8.html"}]);